import subprocess
def pipe(cmds):
    # cmds list of lists
    inp=None
    for c in cmds:
        p=subprocess.run(["./executable"]+c,input=inp,capture_output=True,text=True); inp=p.stdout
    print(cmds, repr(inp), p.stderr)
# format hsv for hsl inputs at extremes (direct)
def r(c):
