import json,math,random
D=json.load(open("/tmp/cb_data.json")); colors=[tuple(x) for x in D["colors"]]; data={k:[tuple(x) for x in v] for k,v in D["data"].items()}
def lin(c):
 c=c/255; return c/12.92 if c<=0.04045 else ((c+0.055)/1.055)**2.4
