 return 12.92*c if c<=0.0031308 else 1.055*(c**(1/2.4))-0.055 if c>0 else 12.92*c
def u8_from_lin(x):
 v=enc(x)*255; return max(0,min(255,math.floor(v+0.5) if v>=0 else -math.floor(-v+0.5)))
# precompute lin inputs
X=[[lin(c) for c in inp] for inp in colors]
def solve(A,b):
 n=3; M=[row[:]+[b[i]] for i,row in enumerate(A)]
 for col in range(n):
  piv=max(range(col,n),key=lambda r:abs(M[r][col])); M[col],M[piv]=M[piv],M[col]
  d=M[col][col]; M[col]=[x/d for x in M[col]]
  for r in range(n):
   if r!=col:
    f=M[r][col]; M[r]=[x-f*y for x,y in zip(M[r],M[col])]
 return [M[i][-1] for i in range(n)]
def lsq(typ,ch):
 A=[[0]*3 for _ in range(3)]; b=[0]*3
 for x,inp,ref in zip(X,colors,data[typ]):
  if ref[ch]<=0 or ref[ch]>=255: continue
  y=lin(ref[ch])
  for i in range(3):
   b[i]+=x[i]*y
   for j in range(3): A[i][j]+=x[i]*x[j]
 return solve(A,b)
def score(coef,typ,ch):
 mism=0; err=0
 for x,ref in zip(X,data[typ]):
  pred=u8_from_lin(sum(coef[j]*x[j] for j in range(3)))
  if pred!=ref[ch]: mism+=1; err+=abs(pred-ref[ch])
 return (mism,err)
random.seed(1)
result={}
for typ in ["prot","deuter","trit"]:
 mat=[]
 print("\n",typ)
 for ch in range(3):
  coef=lsq(typ,ch); best=score(coef,typ,ch)
  # coordinate descent
  for scale in [0.02,0.01,0.005,0.002,0.001,0.0005,0.0002,0.0001,0.00005,0.00002,0.00001]:
   improved=True
   while improved:
    improved=False
    for j in range(3):
     for dir in [scale,-scale]:
      cand=coef[:]; cand[j]+=dir; s=score(cand,typ,ch)
      if s<best: coef, best = cand, s; improved=True
  # random perturbations
  for iter in range(2000):
   cand=[coef[j]+random.uniform(-0.001,0.001) for j in range(3)]; s=score(cand,typ,ch)
   if s<best: coef,best=cand,s
  for scale in [0.0005,0.0002,0.0001,0.00005,0.00002,0.00001,0.000005]:
   improved=True
   while improved:
    improved=False
    for j in range(3):
     for dir in [scale,-scale]:
      cand=coef[:]; cand[j]+=dir; s=score(cand,typ,ch)
      if s<best: coef,best=cand,s; improved=True
  mat.append(coef); print(" ch",ch,[round(x,7) for x in coef],"score mism/err",best)
 result[typ]=mat
json.dump(result,open("/tmp/cb_mat.json","w"),indent=1)
print(result)
