import os,pty,subprocess,select
def run(args, out_tty=False, err_tty=False, env=None, inp=b""):
    masters=[]
    def make():
        m,s=pty.openpty(); masters.append(m); return s
    stdout_fd = make() if out_tty else subprocess.PIPE
    stderr_fd = make() if err_tty else subprocess.PIPE
    e=dict(os.environ); e.update(env or {})
    p=subprocess.Popen(["./executable"]+args, stdout=stdout_fd, stderr=stderr_fd, stdin=subprocess.PIPE, env=e)
    if out_tty: os.close(stdout_fd)
    if err_tty: os.close(stderr_fd)
    p.stdin.write(inp); p.stdin.close()
    outs={m:b"" for m in masters}
    # read pipes via communicate-ish manual: if tty, read until process ends using select
    import time
    while p.poll() is None:
        if masters:
            r,_,_=select.select(masters,[],[],0.1)
            for m in r:
                try:
                    d=os.read(m,65536)
                except OSError: d=b""
                outs[m]+=d
        else: break
    # drain ttys
    for m in masters:
