use crate::color::*;
use crate::named::NAMED_COLORS;

pub fn parse_color(input: &str) -> Option<Color> {
    let s = input.trim();
    if let Some(c) = parse_named(s) {
        return Some(c);
    }
    // Try the various syntactic forms; each must consume the whole input.
    if let Some(c) = parse_hex(s) {
        return Some(c);
    }
    if let Some(c) = parse_function(s) {
        return Some(c);
    }
    if let Some(c) = parse_bare_rgb(s) {
        return Some(c);
    }
    None
}

fn parse_named(s: &str) -> Option<Color> {
    if s.is_empty() || !s.chars().all(|c| c.is_ascii_alphabetic()) {
        return None;
    }
    let lower = s.to_ascii_lowercase();
    for (name, r, g, b) in NAMED_COLORS {
        if *name == lower {
            return Some(Color::from_rgba_u8(*r, *g, *b, 1.0));
        }
    }
    None
}

fn parse_hex(s: &str) -> Option<Color> {
    let digits = s.strip_prefix('#').unwrap_or(s);
    if digits.is_empty() || !digits.chars().all(|c| c.is_ascii_hexdigit()) {
        return None;
    }
    let nib = |i: usize| -> u8 { digits.as_bytes()[i].to_string().as_str().chars().next().unwrap().to_digit(16).unwrap() as u8 };
    let byte = |i: usize| -> u8 { u8::from_str_radix(&digits[i..i + 2], 16).unwrap() };
    match digits.len() {
        3 => Some(Color::from_rgba_u8(nib(0) * 17, nib(1) * 17, nib(2) * 17, 1.0)),
        4 => Some(Color::from_rgba_u8(
            nib(0) * 17,
            nib(1) * 17,
            nib(2) * 17,
            (nib(3) * 17) as f64 / 255.0,
        )),
        6 => Some(Color::from_rgba_u8(byte(0), byte(2), byte(4), 1.0)),
        8 => Some(Color::from_rgba_u8(byte(0), byte(2), byte(4), byte(6) as f64 / 255.0)),
        _ => None,
    }
}

// ---------- low level scanners (nom-like) ----------
struct P<'a> {
    s: &'a [u8],
    pos: usize,
}
impl<'a> P<'a> {
    fn new(s: &'a str) -> P<'a> { P { s: s.as_bytes(), pos: 0 } }
    fn rest(&self) -> &'a [u8] { &self.s[self.pos..] }
    fn eof(&self) -> bool { self.pos >= self.s.len() }
    fn peek(&self) -> Option<u8> { self.s.get(self.pos).copied() }
    fn space0(&mut self) {
        while matches!(self.peek(), Some(b' ') | Some(b'\t')) {
            self.pos += 1;
        }
    }
    fn tag(&mut self, t: &str) -> Option<()> {
        if self.rest().starts_with(t.as_bytes()) {
            self.pos += t.len();
            Some(())
        } else {
            None
        }
    }
    fn tag_no_case(&mut self, t: &str) -> Option<()> {
        let r = self.rest();
        if r.len() >= t.len() && r[..t.len()].eq_ignore_ascii_case(t.as_bytes()) {
            self.pos += t.len();
            Some(())
        } else {
            None
        }
    }
    fn char(&mut self, c: u8) -> Option<()> {
        if self.peek() == Some(c) {
            self.pos += 1;
            Some(())
        } else {
            None
        }
    }
    // separator between components: spaces/tabs, optional comma, spaces/tabs
    fn sep(&mut self) {
        self.space0();
        let _ = self.char(b',');
        self.space0();
    }
    fn double(&mut self) -> Option<f64> {
        let start = self.pos;
        let rest = self.rest();
        // special values (no sign allowed for these, matching nom)
        if rest.len() >= 3 && rest[..3].eq_ignore_ascii_case(b"inf") {
            self.pos += 3;
            return Some(f64::INFINITY);
        }
        if rest.len() >= 3 && rest[..3].eq_ignore_ascii_case(b"nan") {
            self.pos += 3;
            return Some(f64::NAN);
        }
        let mut i = self.pos;
        if matches!(self.s.get(i), Some(b'+') | Some(b'-')) {
            i += 1;
        }
        let mut digits = 0usize;
        while self.s.get(i).map(|c| c.is_ascii_digit()).unwrap_or(false) {
            i += 1;
            digits += 1;
        }
        let mut ok = digits > 0;
        if self.s.get(i) == Some(&b'.') {
            i += 1;
            let mut d2 = 0usize;
            while self.s.get(i).map(|c| c.is_ascii_digit()).unwrap_or(false) {
                i += 1;
                d2 += 1;
            }
            if digits > 0 || d2 > 0 {
                ok = true;
            } else {
                ok = false;
            }
        }
        if !ok {
            return None;
        }
        // exponent only if well-formed; otherwise leave it unconsumed
        if matches!(self.s.get(i), Some(b'e') | Some(b'E')) {
            let mut j = i + 1;
            if matches!(self.s.get(j), Some(b'+') | Some(b'-')) {
                j += 1;
            }
            let mut ed = 0usize;
            while self.s.get(j).map(|c| c.is_ascii_digit()).unwrap_or(false) {
                j += 1;
                ed += 1;
            }
            if ed > 0 {
                i = j;
            }
        }
        let text = std::str::from_utf8(&self.s[start..i]).ok()?;
        let v: f64 = text.parse().ok()?;
        self.pos = i;
        Some(v)
    }
    fn percentage(&mut self) -> Option<f64> {
        let v = self.double()?;
        self.char(b'%')?;
        Some(v / 100.0)
    }
    fn alpha(&mut self) -> Option<f64> {
        // percentage or plain number; '%' must directly follow the number
        let save = self.pos;
        if let Some(v) = self.percentage() {
            return Some(v);
        }
        self.pos = save;
        self.double()
    }
    fn angle_degrees(&mut self) -> Option<f64> {
        let v = self.double()?;
        // unit suffixes (exact, lowercase), degree sign is two bytes in UTF-8
        if self.tag("deg").is_some() {
            Some(v)
        } else if self.tag("grad").is_some() {
            Some(v * 360.0 / 400.0)
        } else if self.tag("rad").is_some() {
            Some(v * 180.0 / std::f64::consts::PI)
        } else if self.tag("turn").is_some() {
            Some(v * 360.0)
        } else if self.tag("\u{00b0}").is_some() {
            Some(v)
        } else {
            Some(v)
        }
    }
}

fn parse_function(s: &str) -> Option<Color> {
    // rgb / rgba
    if let Some(c) = try_rgb(s) { return Some(c); }
    if let Some(c) = try_hsl_hsv(s, true) { return Some(c); }
    if let Some(c) = try_hsl_hsv(s, false) { return Some(c); }
    if let Some(c) = try_lab_like(s) { return Some(c); }
    if let Some(c) = try_gray(s) { return Some(c); }
    None
}

fn components3<F: Fn(&mut P) -> Option<f64>>(p: &mut P, comp: F, allow_alpha: bool) -> Option<(f64, f64, f64, f64)> {
    p.char(b'(')?;
    p.space0();
    let a = comp(p)?;
    p.sep();
    let b = comp(p)?;
    p.sep();
    let c = comp(p)?;
    let mut alpha = 1.0;
    if allow_alpha {
        let save = p.pos;
        // try an optional fourth (alpha) component; the separator is
        // handled in the same way as between the other components.
        let save2 = p.pos;
        p.sep();
        if p.peek() == Some(b')') {
            p.pos = save2;
        } else if let Some(al) = p.alpha() {
            alpha = al;
        } else {
            p.pos = save;
            return None;
        }
    }
    p.space0();
    p.char(b')')?;
    if !p.eof() { return None; }
    Some((a, b, c, alpha))
}

fn try_rgb(s: &str) -> Option<Color> {
    // percent form and numeric form are distinct alternatives
    for percent in [true, false] {
        let mut p = P::new(s);
        if p.tag("rgb").is_none() { continue; }
        let _ = p.char(b'a');
        let r = if percent {
            components3(&mut p, |p| p.percentage(), true)
        } else {
            components3(&mut p, |p| p.double(), true)
        };
        if let Some((a, b, c, al)) = r {
            if percent {
                return Some(Color::from_rgba_01(a, b, c, al));
            } else {
                return Some(Color::from_rgba_255(a, b, c, al));
            }
        }
    }
    None
}

fn parse_bare_rgb(s: &str) -> Option<Color> {
    for percent in [true, false] {
        let mut p = P::new(s);
        let comp = |p: &mut P| if percent { p.percentage() } else { p.double() };
        let a = comp(&mut p)?;
        p.sep();
        let b = comp(&mut p)?;
        p.sep();
        let c = comp(&mut p)?;
        let mut alpha = 1.0;
        if !p.eof() {
            p.sep();
            if p.eof() { return None; }
            alpha = p.alpha()?;
        }
        if !p.eof() { continue; }
        return if percent {
            Some(Color::from_rgba_01(a, b, c, alpha))
        } else {
            Some(Color::from_rgba_255(a, b, c, alpha))
        };
    }
    None
}

fn try_hsl_hsv(s: &str, hsl: bool) -> Option<Color> {
    let mut p = P::new(s);
    if p.tag(if hsl { "hsl" } else { "hsv" }).is_none() { return None; }
    let _ = p.char(b'a');
    p.char(b'(')?;
    p.space0();
    let h = p.angle_degrees()?;
    p.sep();
    let x = p.percentage()?;
    p.sep();
    let y = p.percentage()?;
    let mut alpha = 1.0;
    let save = p.pos;
    p.sep();
    if p.peek() == Some(b')') {
        // no alpha; backtrack is not needed other than position for ')'
    } else if let Some(al) = p.alpha() {
        alpha = al;
    } else {
        p.pos = save;
        // If there was a separator but no parseable alpha and the next
        // char is not ')', this will fail below, as desired.
        if p.peek() != Some(b')') && save != p.pos { return None; }
        // re-apply separator consumption state: we are right after y;
        // space before ')' is handled next
    }
    p.space0();
    p.char(b')')?;
    if !p.eof() { return None; }
    if hsl {
        Some(Color::from_hsl(h, x, y, alpha))
    } else {
        Some(Color::from_hsv(h, x, y, alpha))
    }
}

fn try_lab_like(s: &str) -> Option<Color> {
    // OkLCh, OkLab, LCh, Lab -- case-insensitive prefixes
    struct Spec { tag: &'static str, kind: u8 } // 0 Lab 1 LCh 2 OkLab 3 OkLCh
    let specs = [
        Spec { tag: "oklch", kind: 3 },
        Spec { tag: "oklab", kind: 2 },
        Spec { tag: "lch", kind: 1 },
        Spec { tag: "lab", kind: 0 },
    ];
    for spec in specs {
        let mut p = P::new(s);
        if p.tag_no_case(spec.tag).is_none() { continue; }
        // third component is a hue angle for the *Ch forms
        p.char(b'(')?;
        p.space0();
        let a = p.double()?;
        p.sep();
        let b = p.double()?;
        p.sep();
        let c = if spec.kind == 1 || spec.kind == 3 { p.angle_degrees()? } else { p.double()? };
        let mut alpha = 1.0;
        let save = p.pos;
        p.sep();
        if p.peek() == Some(b')') {
        } else if let Some(al) = p.alpha() {
            alpha = al;
        } else {
            p.pos = save;
        }
        p.space0();
        if p.char(b')').is_none() || !p.eof() { continue; }
        return Some(match spec.kind {
            0 => Color::from_lab(a, b, c, alpha),
            1 => Color::from_lch(a, b, c, alpha),
            2 => Color::from_oklab(a, b, c, alpha),
            _ => Color::from_oklch(a, b, c, alpha),
        });
    }
    None
}

fn try_gray(s: &str) -> Option<Color> {
    let mut p = P::new(s);
    p.tag("gray")?;
    p.char(b'(')?;
    p.space0();
    let mut q = P { s: p.s, pos: p.pos };
    let v = if let Some(v) = q.percentage() {
        p.pos = q.pos;
        v
    } else {
        p.double()?
    };
    // Gray values must be non-negative (this also rejects NaN).
    if !(v >= 0.0) {
        return None;
    }
    p.space0();
    p.char(b')')?;
    if !p.eof() { return None; }
    let g = comp01_to_u8(v);
    Some(Color::from_rgba_u8(g, g, g, 1.0))
}
RS"}

