{"command":"cat > src/ansi.rs <<'RS'
use crate::color::*;

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum ColorModeKind {
    Mode24,
    Mode8,
    Off,
}

/// Convert an RGB colour to the closest 8-bit (256 colour) ANSI code.
/// The palette colours are compared in CIEDE2000 space over the
/// 6x6x6 cube and the grey ramp (codes 16..=255).
pub fn to_ansi8bit(r: u8, g: u8, b: u8) -> u8 {
    // Fast path for greys is unnecessary; brute force is fine.
    let target = crate::color::Color::from_rgba_u8(r, g, b, 1.0).to_lab();
    let mut best = 16u8;
    let mut best_d = f64::INFINITY;
    let levels = [0u8, 95, 135, 175, 215, 255];
    let mut consider = |code: u8, pr: u8, pg: u8, pb: u8, best: &mut u8, best_d: &mut f64| {
        let lab = crate::color::Color::from_rgba_u8(pr, pg, pb, 1.0).to_lab();
        let d = delta_e_2000(target, lab);
        if d < *best_d {
            *best_d = d;
            *best = code;
        }
    };
    for ri in 0..6 {
        for gi in 0..6 {
            for bi in 0..6 {
                let code = 16 + (ri * 36 + gi * 6 + bi) as u8;
                consider(code, levels[ri as usize], levels[gi as usize], levels[bi as usize], &mut best, &mut best_d);
            }
        }
    }
    for i in 0..24 {
        let v = 8 + i * 10;
        consider(232 + i as u8, v, v, v, &mut best, &mut best_d);
    }
    best
}

fn fg_code(mode: ColorModeKind, c: &Color) -> String {
    let (r, g, b) = c.to_rgb_u8();
    match mode {
        ColorModeKind::Mode24 => format!("38;2;{};{};{}", r, g, b),
        ColorModeKind::Mode8 => format!("38;5;{}", to_ansi8bit(r, g, b)),
        ColorModeKind::Off => String::new(),
    }
}
fn bg_code(mode: ColorModeKind, c: &Color) -> String {
    let (r, g, b) = c.to_rgb_u8();
    match mode {
        ColorModeKind::Mode24 => format!("48;2;{};{};{}", r, g, b),
        ColorModeKind::Mode8 => format!("48;5;{}", to_ansi8bit(r, g, b)),
        ColorModeKind::Off => String::new(),
    }
}

