{"command":"cat > src/picker.rs <<'RS'
use crate::ansi::*;
use crate::color::*;
use crate::error::PastelError;
use crate::parser::parse_color;
use std::cell::Cell;
use std::process::Command;

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum DetectedMode {
    M24,
    M8,
    Off,
}

/// Detect the colour mode for the spectrum printed to stderr.
/// This is intentionally independent of the stdout colour mode and
/// of any `--color-mode` command-line flag.
fn detect_stderr_mode() -> Result<ColorModeKind, PastelError> {
    use std::io::IsTerminal;
    if !std::io::stderr().is_terminal() {
        return Ok(ColorModeKind::Off);
    }
    if let Ok(v) = std::env::var("PASTEL_COLOR_MODE") {
        return match v.as_str() {
            "24bit" => Ok(ColorModeKind::Mode24),
            "8bit" => Ok(ColorModeKind::Mode8),
            "off" => Ok(ColorModeKind::Off),
            _ => Err(PastelError::UnknownColorModeValue(v)),
        };
    }
    if std::env::var_os("NO_COLOR").is_some() {
        return Ok(ColorModeKind::Off);
    }
    match std::env::var("COLORTERM").unwrap_or_default().as_str() {
        "truecolor" | "24bit" => Ok(ColorModeKind::Mode24),
        _ => Ok(ColorModeKind::Mode8),
    }
}

thread_local! {
    static SPECTRUM_PRINTED: Cell<bool> = Cell::new(false);
}

pub fn print_spectrum_once() -> Result<(), PastelError> {
    let already = SPECTRUM_PRINTED.with(|c| c.get());
    if already {
        return Ok(());
    }
    print_spectrum()?;
    SPECTRUM_PRINTED.with(|c| c.set(true));
    Ok(())
}

pub fn print_spectrum() -> Result<(), PastelError> {
    let mode = detect_stderr_mode()?;
    let mut canvas = Canvas::new(52, 52);
    let white = Color::from_rgba_u8(255, 255, 255, 1.0);
    // white frame
    for x in 2..=51 {
        canvas.draw_pixel(x, 2, white);
        canvas.draw_pixel(x, 51, white);
    }
    for y in 2..=51 {
        canvas.draw_pixel(2, y, white);
        canvas.draw_pixel(51, y, white);
    }
    // spectrum interior: hue across, lightness down
    for iy in 0..48usize {
        for ix in 0..48usize {
            let hue = ix as f64 * 360.0 / 48.0;
            let lightness = iy as f64 / 47.0;
            let color = spectrum_color(hue, lightness);
            canvas.draw_pixel(3 + ix, 3 + iy, color);
        }
    }
    eprint!("{}", canvas.render(mode));
    eprintln!();
    SPECTRUM_PRINTED.with(|c| c.set(true));
    Ok(())
}

fn spectrum_color(hue: f64, t: f64) -> Color {
    // t: 0 (black) .. 1 (white).  Build the colour by taking a vivid
    // colour for the hue and varying its Lab lightness at the chroma
    // that keeps it colourful across the range (this approximates the
    // reference spectrum closely enough for the plain-text form,
    // which is what non-terminal output contains).
    let _ = hue;
    let _ = t;
    // Placeholder implementation replaced by the LCh-based one below.
    spectrum_color_lch(hue, t)
}

fn spectrum_color_lch(hue_hsl: f64, t: f64) -> Color {
    // Convert the vivid HSL colour to LCh, then sweep LCh lightness
    // from 0 to 100, scaling chroma by a parabola peaking near L=55.
    let vivid = Color::from_hsl(hue_hsl, 1.0, 0.5, 1.0);
    let (_l0, _c0, h_lch) = vivid.to_lch();
    let l = t * 100.0;
    let chroma = 90.0 * (1.0 - ((l - 55.0) / 70.0).powi(2)).max(0.0);
    Color::from_lch(l, chroma, h_lch, 1.0)
}

