        rest = rest[end..].trim_start();
        if idx < 2 {
            rest = rest.strip_prefix(',')?.trim_start();
        }
    }
    Some((vals[0], vals[1], vals[2]))
}

pub fn pick_color(requested: Option<&str>) -> Result<Color, PastelError> {
    print_spectrum_once()?;
    let tool = match find_tool(requested) {
        Some(t) => t,
        None => return Err(PastelError::NoColorPickerFound),
    };
    let output = Command::new(tool.exe)
        .args(tool.pick_args)
        .output()
        .map_err(|_| PastelError::ColorPickerExecutionFailed(tool.exe.to_string()))?;
    if !output.status.success() {
        return Err(PastelError::ColorPickerExecutionFailed(tool.exe.to_string()));
    }
    let text = String::from_utf8(output.stdout).map_err(|_| PastelError::InvalidUtf8)?;
    let color_str = if tool.gdbus {
        parse_gdbus_output(&text)
    } else {
        text.trim().to_string()
    };
    parse_color(&color_str).ok_or_else(|| PastelError::ColorParseError(color_str))
}
RS"}

