use std::fmt;

#[derive(Debug)]
pub enum PastelError {
    ColorParseError(String),
    NumberParseError(String),
    CouldNotReadColorFromStdin,
    NoColorPickerFound,
    ColorPickerExecutionFailed(String),
    InvalidUtf8,
    IoError(String),
    UnknownColorModeValue(String),
    Message(String),
}

impl fmt::Display for PastelError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            PastelError::ColorParseError(s) => write!(f, "Could not parse color '{}'", s),
            PastelError::NumberParseError(s) => write!(f, "Could not parse number '{}'", s),
            PastelError::CouldNotReadColorFromStdin => write!(f, "Could not read color from standard input"),
            PastelError::NoColorPickerFound => write!(f, "Could not find any external color picker tool. See 'pastel pick --help' for more information."),
            PastelError::ColorPickerExecutionFailed(name) => write!(f, "Error while running color picker '{}'", name),
            PastelError::InvalidUtf8 => write!(f, "Color input contains invalid UTF8"),
            PastelError::IoError(msg) => write!(f, "I/O error: {}", msg),
            PastelError::UnknownColorModeValue(v) => write!(f, "Unknown PASTEL_COLOR_MODE value ({})", v),
            PastelError::Message(m) => write!(f, "{}", m),
        }
    }
}
impl std::error::Error for PastelError {}

pub type Result<T> = std::result::Result<T, PastelError>;

pub fn parse_number<T>(s: &str) -> Result<T>
where
    T: std::str::FromStr,
{
    s.parse::<T>().map_err(|_| PastelError::NumberParseError(s.to_string()))
}
RS"}

