fn amount_cmd(name: &'static str, about: &'static str, long_about: &'static str, amount_help: &'static str) -> Command {
    Command::new(name)
        .about(about)
        .long_about(long_about)
        .arg(Arg::new("amount").value_name("amount").required(true).help(amount_help))
        .arg(color_arg_named("color"))
}
fn simple_cmd(name: &'static str, about: &'static str, long_about: &'static str) -> Command {
    Command::new(name).about(about).long_about(long_about).arg(color_arg())
}

// ---------------- configuration ----------------

struct Config {
    mode: ColorModeKind,
    interactive: bool,
    show_warning: bool,
    picker: Option<String>,
}

fn make_config(matches: &clap::ArgMatches) -> std::result::Result<Config, PastelError> {
    let interactive = io::stdout().is_terminal();
    let force = matches.get_flag("force-color");
    let requested = matches.get_one::<String>("color-mode").map(|s| s.as_str()).unwrap_or("auto");
    let mut show_warning = false;
    let mode = if force {
        ColorModeKind::Mode24
    } else {
        match requested {
            "24bit" => ColorModeKind::Mode24,
            "8bit" => ColorModeKind::Mode8,
            "off" => ColorModeKind::Off,
            _ => {
                // auto
                if !interactive {
                    ColorModeKind::Off
                } else if let Ok(v) = std::env::var("PASTEL_COLOR_MODE") {
                    match v.as_str() {
                        "24bit" => ColorModeKind::Mode24,
                        "8bit" => ColorModeKind::Mode8,
                        "off" => ColorModeKind::Off,
                        _ => return Err(PastelError::UnknownColorModeValue(v)),
                    }
                } else if std::env::var_os("NO_COLOR").is_some() {
                    ColorModeKind::Off
                } else {
                    match std::env::var("COLORTERM").unwrap_or_default().as_str() {
                        "truecolor" | "24bit" => ColorModeKind::Mode24,
                        _ => {
                            show_warning = true;
                            ColorModeKind::Mode8
                        }
                    }
                }
            }
        }
    };
    Ok(Config {
        mode,
        interactive,
        show_warning,
        picker: matches.get_one::<String>("color-picker").cloned(),
    })
}

const WARNING_TEXT: &str = "Your terminal emulator does not appear to support 24-bit colors (this means that the COLORTERM environment variable is not set to 'truecolor' or '24bit'). pastel will fall back to 8-bit colors, but you will only be able to see rough approximations of the real colors.\n\nTo fix this, follow these steps:\n  1. Run 'pastel colorcheck' to test if your terminal\n     emulator does support 24-bit colors. If this is the\n     case, set 'PASTEL_COLOR_MODE=24bit' to force 24-bit\n     mode and to remove this warning. Alternatively, make\n     sure that COLORTERM is properly set by your terminal\n     emulator.\n  2. If your terminal emulator does not support 24-bit\n     colors, set 'PASTEL_COLOR_MODE=8bit' to remove this\n     warning or try a different terminal emulator.\n\nFor more information, see https://gist.github.com/XVilka/8346728\n";

fn print_warning(cfg: &Config) {
    let mut st = Style::new();
    st.fg = Some(Color::from_rgba_u8(255, 255, 0, 1.0));
    eprintln!("{}: {}", st.paint(cfg.mode, "[pastel warning]"), WARNING_TEXT);
}

fn print_error(cfg: Option<&Config>, err: &PastelError) {
    match cfg {
        Some(cfg) if cfg.mode != ColorModeKind::Off => {
            let mut st = Style::new();
            st.fg = Some(Color::from_rgba_u8(255, 0, 0, 1.0));
            eprintln!("{}: {}", st.paint(cfg.mode, "[pastel error]"), err);
        }
        _ => eprintln!("[pastel error]: {}", err),
    }
}

// ---------------- stdin handling ----------------

struct StdIn {
    lock: io::StdinLock<'static>,
}
impl StdIn {
    fn new() -> StdIn { StdIn { lock: io::stdin().lock() } }
    /// Read one line without its line ending; None at EOF (0 bytes).
    fn read_line(&mut self) -> error::Result<Option<String>> {
        let mut buf = String::new();
        let n = self.lock.read_line(&mut buf).map_err(|e| {
            if e.kind() == io::ErrorKind::InvalidData {
                PastelError::InvalidUtf8
            } else {
                PastelError::IoError(e.to_string())
            }
        })?;
        if n == 0 {
            return Ok(None);
        }
        if buf.ends_with('\n') {
            buf.pop();
            if buf.ends_with('\r') { buf.pop(); }
        }
        Ok(Some(buf))
    }
    fn read_rest(&mut self) -> error::Result<String> {
        let mut buf = String::new();
        self.lock.read_to_string(&mut buf).map_err(|e| PastelError::IoError(e.to_string()))?;
        Ok(buf)
    }
}

fn color_from_arg(arg: &str, cfg: &Config, stdin: &mut StdIn) -> error::Result<Color> {
    if arg == "-" {
        match stdin.read_line()? {
            Some(line) => parser::parse_color(&line).ok_or_else(|| PastelError::ColorParseError(line)),
            None => Err(PastelError::CouldNotReadColorFromStdin),
        }
    } else if arg == "pick" {
        picker::pick_color(cfg.picker.as_deref())
    } else {
        parser::parse_color(arg).ok_or_else(|| PastelError::ColorParseError(arg.to_string()))
    }
}

fn get_color_args<'a>(m: &'a clap::ArgMatches, id: &str) -> Vec<&'a String> {
    match m.get_many::<String>(id) {
        Some(v) => v.collect(),
        None => Vec::new(),
    }
}

/// Iterate colours from arguments, or from stdin if there are none.
/// Calls `f` for each colour; parsing is streamed (an error stops
/// after earlier colours have been processed).
fn for_each_color<F: FnMut(Color) -> error::Result<()>>(
    cfg: &Config,
    stdin: &mut StdIn,
    args: &[&String],
    mut f: F,
) -> error::Result<()> {
    if args.is_empty() {
        while let Some(line) = stdin.read_line()? {
            let c = parser::parse_color(&line).ok_or_else(|| PastelError::ColorParseError(line.clone()))?;
            f(c)?;
        }
        Ok(())
    } else {
        for a in args {
            let c = color_from_arg(a, cfg, stdin)?;
            f(c)?;
        }
        Ok(())
    }
}

fn collect_colors(cfg: &Config, stdin: &mut StdIn, args: &[&String]) -> error::Result<Vec<Color>> {
    let mut out = Vec::new();
    for_each_color(cfg, stdin, args, |c| {
        out.push(c);
        Ok(())
    })?;
    Ok(out)
}

// ---------------- printing colours ----------------

fn exact_name(c: &Color) -> Option<&'static str> {
    if c.alpha != 1.0 {
        return None;
    }
    let rgb = c.to_rgb_u8();
    for (name, r, g, b) in named::NAMED_COLORS {
        if (*r, *g, *b) == rgb {
            return Some(name);
        }
    }
    None
}

fn nearest_name(c: &Color) -> &'static str {
    let lab = c.to_lab();
    let mut best: Option<(&'static str, f64)> = None;
    for (name, r, g, b) in named::NAMED_COLORS {
        let nc = Color::from_rgba_u8(*r, *g, *b, 1.0);
        let d = delta_e_2000(lab, nc.to_lab());
        match best {
            Some((_, bd)) if d >= bd => {}
            _ => best = Some((name, d)),
        }
    }
    best.unwrap().0
}

fn most_similar(c: &Color, count: usize) -> Vec<(&'static str, Color)> {
    let lab = c.to_lab();
    let mut v: Vec<(&'static str, Color, f64)> = named::NAMED_COLORS
        .iter()
        .map(|(name, r, g, b)| {
            let nc = Color::from_rgba_u8(*r, *g, *b, 1.0);
            (*name, nc, delta_e_2000(lab, nc.to_lab()))
        })
        .collect();
    v.sort_by(|a, b| a.2.partial_cmp(&b.2).unwrap_or(std::cmp::Ordering::Equal));
    v.dedup_by(|a, b| a.1.to_rgb_u8() == b.1.to_rgb_u8());
    v.into_iter().take(count).map(|(n, col, _)| (n, col)).collect()
}

fn print_color(cfg: &Config, color: &Color) {
    if cfg.interactive {
        show_color(cfg, color);
    } else {
        println!("{}", color);
    }
}

fn show_color(cfg: &Config, color: &Color) {
    // Build the 16x16 checkerboard canvas with the colour inset.
    let mut canvas = Canvas::new(16, 16);
    let light = (240u8, 240u8, 240u8);
    let dark = (181u8, 181u8, 181u8);
    for y in 0..16 {
        for x in 0..16 {
            let chk = if (x + y) % 2 == 0 { light } else { dark };
            canvas.draw_pixel(x, y, Color::from_rgba_u8(chk.0, chk.1, chk.2, 1.0));
        }
    }
    for y in 2..14 {
        for x in 2..14 {
            let chk = if (x + y) % 2 == 0 { light } else { dark };
            let px = if color.alpha < 1.0 { blend_over(color, chk) } else { *color };
            canvas.draw_pixel(x, y, px);
        }
    }
    let rendered = canvas.render(cfg.mode);
    let canvas_lines: Vec<&str> = rendered.split_inclusive('\n').collect();

    // info lines
    enum Info {
        Text(String),
        Similar(&'static str, Color),
    }
    let mut infos: Vec<Info> = Vec::new();
    let name = exact_name(color);
    if let Some(n) = name {
        infos.push(Info::Text(format!("Name: {}", n)));
    }
    infos.push(Info::Text(format!("Hex: {}", color.to_hex_string())));
    infos.push(Info::Text(format!("RGB: {}", color.to_rgb_string())));
    infos.push(Info::Text(format!("HSL: {}", color.to_hsl_string(true))));
    infos.push(Info::Text(String::new()));
    infos.push(Info::Text("Most similar:".to_string()));
    for (n, col) in most_similar(color, 10) {
        if infos.len() >= 8 { break; }
        if Some(n) == name { continue; }
        infos.push(Info::Similar(n, col));
    }
    while infos.len() < 8 {
        infos.push(Info::Text(String::new()));
    }

    println!();
    for i in 0..8 {
        let canvas_line = canvas_lines.get(i).map(|s| s.trim_end_matches('\n')).unwrap_or("");
        let info_str = match &infos[i] {
            Info::Text(t) => {
                let mut s = t.clone();
                while s.chars().count() < 40 { s.push(' '); }
                s
            }
            Info::Similar(n, col) => {
                let mut sw = Canvas::new(5, 2);
                sw.draw_rect(0, 0, 5, 2, *col);
                let sw_rendered = sw.render(cfg.mode);
                let sw_line = sw_rendered.trim_end_matches('\n');
                let mut s = format!("   {} {}", sw_line, n);
                let visible = 3 + 5 + 1 + n.chars().count();
                for _ in visible..40 { s.push(' '); }
                s
            }
        };
        println!("  {}  {}", canvas_line, info_str);
    }
    println!();
}

// ---------------- RNG ----------------

struct Rng {
    state: u64,
}
impl Rng {
    fn new() -> Rng {
        let mut seed: u64 = 0;
        if let Ok(bytes) = std::fs::read("/dev/urandom") {
            if bytes.len() >= 8 {
                seed = u64::from_le_bytes(bytes[..8].try_into().unwrap());
            }
        }
        if seed == 0 {
            let t = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default();
            seed = t.as_nanos() as u64 ^ (std::process::id() as u64) << 32 ^ 0x9e3779b97f4a7c15;
        }
        Rng { state: seed }
    }
    fn next_u64(&mut self) -> u64 {
        // splitmix64
        self.state = self.state.wrapping_add(0x9e3779b97f4a7c15);
        let mut z = self.state;
        z = (z ^ (z >> 30)).wrapping_mul(0xbf58476d1ce4e5b9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94d049bb133111eb);
        z ^ (z >> 31)
    }
    fn f64(&mut self) -> f64 {
        (self.next_u64() >> 11) as f64 * (1.0 / 9007199254740992.0)
    }
    fn range(&mut self, lo: f64, hi: f64) -> f64 {
        lo + (hi - lo) * self.f64()
    }
    fn u8(&mut self) -> u8 { self.next_u64() as u8 }
    fn usize_range(&mut self, n: usize) -> usize {
        if n == 0 { 0 } else { (self.next_u64() % n as u64) as usize }
    }
    fn shuffle<T>(&mut self, v: &mut [T]) {
        for i in (1..v.len()).rev() {
            let j = self.usize_range(i + 1);
            v.swap(i, j);
        }
    }
    fn bool_prob(&mut self, p: f64) -> bool { self.f64() < p }
}

// ---------------- sorting ----------------

#[derive(Clone, Copy, PartialEq)]
enum SortOrderKind { Brightness, Luminance, Hue, Chroma, Random }

fn parse_sort_order(s: &str) -> SortOrderKind {
    match s {
        "brightness" => SortOrderKind::Brightness,
        "luminance" => SortOrderKind::Luminance,
        "chroma" => SortOrderKind::Chroma,
        "random" => SortOrderKind::Random,
        _ => SortOrderKind::Hue,
    }
}

fn sort_key(c: &Color, order: SortOrderKind) -> f64 {
    match order {
        SortOrderKind::Brightness => c.brightness(),
        SortOrderKind::Luminance => c.luminance(),
        SortOrderKind::Hue => c.to_lch().2,
        SortOrderKind::Chroma => c.to_lch().1,
        SortOrderKind::Random => 0.0,
    }
}

fn sort_colors<T, F: Fn(&T) -> &Color>(v: &mut Vec<T>, order: SortOrderKind, rng: &mut Rng, get: F) {
    match order {
        SortOrderKind::Random => {
            // Fisher-Yates by index is awkward with a getter; shuffle directly
            for i in (1..v.len()).rev() {
                let j = rng.usize_range(i + 1);
                v.swap(i, j);
            }
        }
        _ => {
            v.sort_by(|a, b| {
                let ka = sort_key(get(a), order);
                let kb = sort_key(get(b), order);
                ka.partial_cmp(&kb).unwrap_or(std::cmp::Ordering::Equal)
            });
        }
    }
}

// ---------------- interpolation ----------------

#[derive(Clone, Copy, PartialEq)]
enum Space { Lab, LCh, Rgb, Hsl, OkLab }

fn parse_space(s: &str) -> Space {
    match s.to_ascii_lowercase().as_str() {
        "lch" => Space::LCh,
        "rgb" => Space::Rgb,
        "hsl" => Space::Hsl,
        "oklab" => Space::OkLab,
        _ => Space::Lab,
    }
}

fn lerp(a: f64, b: f64, t: f64) -> f64 { a + (b - a) * t }

fn interpolate_hue(a: f64, b: f64, t: f64) -> f64 {
    let mut diff = b - a;
    if diff > 180.0 {
        diff -= 360.0;
    } else if diff < -180.0 {
        diff += 360.0;
    }
    (a + diff * t).rem_euclid(360.0)
}

fn interpolate(c1: &Color, c2: &Color, t_raw: f64, space: Space) -> Color {
    let t = clamp_factor(t_raw);
    let alpha = lerp(c1.alpha, c2.alpha, t);
    match space {
        Space::Rgb => {
            let a = c1.to_rgb_float();
            let b = c2.to_rgb_float();
            Color::from_rgba_01(lerp(a.0, b.0, t), lerp(a.1, b.1, t), lerp(a.2, b.2, t), alpha)
        }
        Space::Hsl => {
            Color {
                hue: interpolate_hue(c1.hue, c2.hue, t),
                saturation: clamp01(lerp(c1.saturation, c2.saturation, t)),
                lightness: clamp01(lerp(c1.lightness, c2.lightness, t)),
                alpha: clamp01(alpha),
            }
        }
        Space::Lab => {
            let a = c1.to_lab();
            let b = c2.to_lab();
            Color::from_lab(lerp(a.0, b.0, t), lerp(a.1, b.1, t), lerp(a.2, b.2, t), alpha)
        }
        Space::LCh => {
            let a = c1.to_lch();
            let b = c2.to_lch();
            Color::from_lch(lerp(a.0, b.0, t), lerp(a.1, b.1, t), interpolate_hue(a.2, b.2, t), alpha)
        }
        Space::OkLab => {
            let a = c1.to_oklab();
            let b = c2.to_oklab();
            Color::from_oklab(lerp(a.0, b.0, t), lerp(a.1, b.1, t), lerp(a.2, b.2, t), alpha)
        }
    }
}

// ---------------- format ----------------

fn format_color(c: &Color, ty: &str) -> String {
    match ty.to_ascii_lowercase().as_str() {
        "rgb" => c.to_rgb_string(),
        "rgb-float" => c.to_rgb_float_string(),
        "rgb-r" => format!("{}", c.to_rgb_u8().0),
        "rgb-g" => format!("{}", c.to_rgb_u8().1),
        "rgb-b" => format!("{}", c.to_rgb_u8().2),
        "hex" => c.to_hex_string(),
        "hsl" => c.to_hsl_string(true),
        "hsl-hue" => format!("{:.0}", c.hue),
        "hsl-saturation" => format!("{:.4}", c.saturation),
        "hsl-lightness" => format!("{:.4}", c.lightness),
        "hsv" => {
            let (h, s, v) = c.to_hsv();
            if c.alpha < 1.0 {
                format!("hsva({:.0}, {:.1}%, {:.1}%, {})", h, s * 100.0, v * 100.0, format_alpha(c.alpha))
            } else {
                format!("hsv({:.0}, {:.1}%, {:.1}%)", h, s * 100.0, v * 100.0)
            }
        }
        "hsv-hue" => format!("{:.0}", c.to_hsv().0),
        "hsv-saturation" => format!("{:.4}", c.to_hsv().1),
        "hsv-value" => format!("{:.4}", c.to_hsv().2),
        "lch" => {
            let (l, ch, h) = c.to_lch();
            if c.alpha < 1.0 {
                format!("LCh({:.0}, {:.0}, {:.0}, {})", l, ch, h, format_alpha(c.alpha))
            } else {
                format!("LCh({:.0}, {:.0}, {:.0})", l, ch, h)
            }
        }
        "lch-lightness" => format!("{:.2}", c.to_lch().0),
        "lch-chroma" => format!("{:.2}", c.to_lch().1),
        "lch-hue" => format!("{:.2}", c.to_lch().2),
        "oklch" => {
            let (l, ch, h) = c.to_oklch();
            if c.alpha < 1.0 {
                format!("OkLCh({:.4}, {:.4}, {:.4}, {})", l, ch, h, format_alpha(c.alpha))
            } else {
                format!("OkLCh({:.4}, {:.4}, {:.4})", l, ch, h)
            }
        }
        "oklch-lightness" => format!("{:.4}", c.to_oklch().0),
        "oklch-chroma" => format!("{:.4}", c.to_oklch().1),
        "oklch-hue" => format!("{:.4}", c.to_oklch().2),
        "lab" => {
            let (l, a, b) = c.to_lab();
            if c.alpha < 1.0 {
                format!("Lab({:.0}, {:.0}, {:.0}, {})", l, a, b, format_alpha(c.alpha))
            } else {
                format!("Lab({:.0}, {:.0}, {:.0})", l, a, b)
            }
        }
        "lab-a" => format!("{:.2}", c.to_lab().1),
        "lab-b" => format!("{:.2}", c.to_lab().2),
        "oklab" => {
            let (l, a, b) = c.to_oklab();
            if c.alpha < 1.0 {
                format!("OkLab({:.4}, {:.4}, {:.4}, {})", l, a, b, format_alpha(c.alpha))
            } else {
                format!("OkLab({:.4}, {:.4}, {:.4})", l, a, b)
            }
        }
        "oklab-l" => format!("{:.4}", c.to_oklab().0),
        "oklab-a" => format!("{:.4}", c.to_oklab().1),
        "oklab-b" => format!("{:.4}", c.to_oklab().2),
        "luminance" => format!("{:.3}", c.luminance()),
        "brightness" => format!("{:.3}", c.brightness()),
        "ansi-8bit" => {
            let (r, g, b) = c.to_rgb_u8();
            format!("\\x1b[38;5;{}m", to_ansi8bit(r, g, b))
        }
        "ansi-24bit" => {
            let (r, g, b) = c.to_rgb_u8();
            format!("\\x1b[38;2;{};{};{}m", r, g, b)
        }
        "ansi-8bit-value" => {
            let (r, g, b) = c.to_rgb_u8();
            format!("{}", to_ansi8bit(r, g, b))
        }
        "cmyk" => {
            let (cy, m, y, k) = c.to_cmyk();
            format!("cmyk({:.0}, {:.0}, {:.0}, {:.0})", cy * 100.0, m * 100.0, y * 100.0, k * 100.0)
        }
        "name" => nearest_name(c).to_string(),
        _ => c.to_hex_string(),
    }
}
RS"}

