// ---------------- command handlers ----------------

fn run(matches: &clap::ArgMatches, cfg: &Config) -> error::Result<()> {
    let (name, sub) = matches.subcommand().unwrap();
    if cfg.show_warning && name != "paint" && name != "colorcheck" {
