        "random" => cmd_random(sub, cfg, &mut rng),
        "distinct" => cmd_distinct(sub, cfg, &mut stdin, &mut rng),
        "sort-by" => cmd_sort_by(sub, cfg, &mut stdin, &mut rng),
        "pick" => cmd_pick(sub, cfg),
        "format" => cmd_format(sub, cfg, &mut stdin),
        "paint" => cmd_paint(sub, cfg, &mut stdin),
        "gradient" => cmd_gradient(sub, cfg, &mut stdin),
        "mix" => cmd_mix(sub, cfg, &mut stdin),
        "colorblind" => {
            let ty = sub.get_one::<String>("type").unwrap().to_ascii_lowercase();
            let args = get_color_args(sub, "color");
            for_each_color(cfg, &mut stdin, &args, |c| {
                print_color(cfg, &colorblind(&c, &ty));
                Ok(())
            })
        }
        "set" => cmd_set(sub, cfg, &mut stdin),
        "saturate" | "desaturate" | "lighten" | "darken" => {
            let amount_s = sub.get_one::<String>("amount").unwrap().clone();
            let args = get_color_args(sub, "color");
            for_each_color(cfg, &mut stdin, &args, |c| {
                let amount: f64 = parse_number(&amount_s)?;
                let out = match name {
                    "saturate" => c.saturate(amount),
                    "desaturate" => c.desaturate(amount),
                    "lighten" => c.lighten(amount),
                    _ => c.darken(amount),
                };
                print_color(cfg, &out);
                Ok(())
            })
        }
        "rotate" => {
            let deg_s = sub.get_one::<String>("degrees").unwrap().clone();
            let args = get_color_args(sub, "color");
            for_each_color(cfg, &mut stdin, &args, |c| {
                let d: f64 = parse_number(&deg_s)?;
                print_color(cfg, &c.rotate_hue(d));
                Ok(())
            })
        }
        "complement" => {
            let args = get_color_args(sub, "color");
            for_each_color(cfg, &mut stdin, &args, |c| {
                print_color(cfg, &c.rotate_hue(180.0));
                Ok(())
            })
        }
        "gray" => {
            let l: f64 = parse_number(sub.get_one::<String>("lightness").unwrap())?;
            print_color(cfg, &Color::from_hsl(0.0, 0.0, l, 1.0));
            Ok(())
        }
        "to-gray" => {
            let args = get_color_args(sub, "color");
            for_each_color(cfg, &mut stdin, &args, |c| {
                print_color(cfg, &c.to_gray());
                Ok(())
            })
        }
        "textcolor" => {
            let args = get_color_args(sub, "color");
            for_each_color(cfg, &mut stdin, &args, |c| {
                print_color(cfg, &c.text_color());
                Ok(())
            })
        }
        "colorcheck" => cmd_colorcheck(),
        _ => Ok(()),
    }
}

fn cmd_format(sub: &clap::ArgMatches, cfg: &Config, stdin: &mut StdIn) -> error::Result<()> {
    let ty = sub.get_one::<String>("type").unwrap().clone();
    let lty = ty.to_ascii_lowercase();
    let args = get_color_args(sub, "color");
    for_each_color(cfg, stdin, &args, |c| {
        if lty == "ansi-8bit-escapecode" {
            print!("{}", ansi_escape_8bit(&c));
        } else if lty == "ansi-24bit-escapecode" {
            print!("{}", ansi_escape_24bit(&c));
        } else {
            let text = format_color(&c, &ty);
            if cfg.mode != ColorModeKind::Off {
                let mut st = Style::new();
                st.fg = Some(c.text_color());
                st.bg = Some(c);
                println!("{}", st.paint(cfg.mode, &text));
            } else {
                println!("{}", text);
            }
        }
        Ok(())
    })
}

fn cmd_list(sub: &clap::ArgMatches, cfg: &Config, rng: &mut Rng) -> error::Result<()> {
    let order = parse_sort_order(sub.get_one::<String>("sort").unwrap());
    let mut v: Vec<(&'static str, Color)> = named::NAMED_COLORS
        .iter()
        .map(|(n, r, g, b)| (*n, Color::from_rgba_u8(*r, *g, *b, 1.0)))
        .collect();
    sort_colors(&mut v, order, rng, |p| &p.1);
    v.dedup_by(|a, b| a.1.to_rgb_u8() == b.1.to_rgb_u8());
    for (name, color) in v {
        if cfg.interactive {
            let text = format!(" {:<23} ", name);
            let mut st = Style::new();
            st.fg = Some(color.text_color());
            st.bg = Some(color);
            println!("{}", st.paint(cfg.mode, &text));
        } else {
            println!("{}", name);
        }
    }
    Ok(())
}

fn cmd_random(sub: &clap::ArgMatches, cfg: &Config, rng: &mut Rng) -> error::Result<()> {
    let count: usize = parse_number(sub.get_one::<String>("number").unwrap())?;
    let strategy = sub.get_one::<String>("strategy").map(|s| s.as_str()).unwrap_or("vivid");
    for _ in 0..count {
        let c = match strategy {
            "rgb" => Color::from_rgba_u8(rng.u8(), rng.u8(), rng.u8(), 1.0),
            "gray" => Color::from_hsl(0.0, 0.0, rng.f64(), 1.0),
            "lch_hue" => Color::from_lch(70.0, 35.0, rng.range(0.0, 360.0), 1.0),
            _ => Color::from_hsl(rng.range(0.0, 360.0), rng.range(0.2, 0.8), rng.range(0.3, 0.7), 1.0),
        };
        print_color(cfg, &c);
    }
    Ok(())
}

fn cmd_sort_by(sub: &clap::ArgMatches, cfg: &Config, stdin: &mut StdIn, rng: &mut Rng) -> error::Result<()> {
    let order = parse_sort_order(sub.get_one::<String>("sort-order").unwrap());
    let args = get_color_args(sub, "color");
    let mut colors = collect_colors(cfg, stdin, &args)?;
    if sub.get_flag("unique") {
        let mut seen = std::collections::HashSet::new();
        colors.retain(|c| seen.insert(c.to_rgb_u8()));
    }
    sort_colors(&mut colors, order, rng, |c| c);
    if sub.get_flag("reverse") {
        colors.reverse();
    }
    for c in &colors {
        print_color(cfg, c);
    }
    Ok(())
}

fn cmd_pick(sub: &clap::ArgMatches, cfg: &Config) -> error::Result<()> {
    let count: usize = parse_number(sub.get_one::<String>("count").unwrap())?;
    picker::print_spectrum()?;
    for _ in 0..count {
        let c = picker::pick_color(cfg.picker.as_deref())?;
        print_color(cfg, &c);
    }
    Ok(())
