fn colorcheck_panels(mode: ColorModeKind) -> String {
    let mut canvas = Canvas::new(30, 12);
    let colors = [(73u8, 39u8, 50u8), (16, 51, 30), (29, 54, 90)];
    for (i, (r, g, b)) in colors.iter().enumerate() {
        canvas.draw_rect(2 + i * 10, 2, 8, 8, Color::from_rgba_u8(*r, *g, *b, 1.0));
