                Ok(())
            })
        }
        "list" => cmd_list(sub, cfg, &mut rng),
        "random" => cmd_random(sub, cfg, &mut rng),
        "distinct" => cmd_distinct(sub, cfg, &mut stdin, &mut rng),
        "sort-by" => cmd_sort_by(sub, cfg, &mut stdin, &mut rng),
        "pick" => cmd_pick(sub, cfg),
        "format" => cmd_format(sub, cfg, &mut stdin),
        "paint" => cmd_paint(sub, cfg, &mut stdin),
        "gradient" => cmd_gradient(sub, cfg, &mut stdin),
        "mix" => cmd_mix(sub, cfg, &mut stdin),
        "colorblind" => {
            let ty = sub.get_one::<String>("type").unwrap().to_ascii_lowercase();
            let args = get_color_args(sub, "color");
            for_each_color(cfg, &mut stdin, &args, |c| {
                print_color(cfg, &colorblind(&c, &ty));
                Ok(())
            })
        }
        "set" => cmd_set(sub, cfg, &mut stdin),
        "saturate" | "desaturate" | "lighten" | "darken" => {
            let amount_s = sub.get_one::<String>("amount").unwrap().clone();
            let args = get_color_args(sub, "color");
            for_each_color(cfg, &mut stdin, &args, |c| {
                let amount: f64 = parse_number(&amount_s)?;
                let out = match name {
                    "saturate" => c.saturate(amount),
                    "desaturate" => c.desaturate(amount),
                    "lighten" => c.lighten(amount),
                    _ => c.darken(amount),
                };
                print_color(cfg, &out);
                Ok(())
            })
        }
        "rotate" => {
            let deg_s = sub.get_one::<String>("degrees").unwrap().clone();
            let args = get_color_args(sub, "color");
            for_each_color(cfg, &mut stdin, &args, |c| {
                let d: f64 = parse_number(&deg_s)?;
                print_color(cfg, &c.rotate_hue(d));
                Ok(())
            })
        }
        "complement" => {
            let args = get_color_args(sub, "color");
            for_each_color(cfg, &mut stdin, &args, |c| {
                print_color(cfg, &c.rotate_hue(180.0));
                Ok(())
            })
        }
        "gray" => {
            let l: f64 = parse_number(sub.get_one::<String>("lightness").unwrap())?;
            print_color(cfg, &Color::from_hsl(0.0, 0.0, l, 1.0));
            Ok(())
        }
        "to-gray" => {
            let args = get_color_args(sub, "color");
            for_each_color(cfg, &mut stdin, &args, |c| {
                print_color(cfg, &c.to_gray());
                Ok(())
            })
        }
        "textcolor" => {
            let args = get_color_args(sub, "color");
            for_each_color(cfg, &mut stdin, &args, |c| {
                print_color(cfg, &c.text_color());
                Ok(())
            })
        }
        "colorcheck" => cmd_colorcheck(),
        _ => Ok(()),
    }
}

fn cmd_format(sub: &clap::ArgMatches, cfg: &Config, stdin: &mut StdIn) -> error::Result<()> {
    let ty = sub.get_one::<String>("type").unwrap().clone();
    let lty = ty.to_ascii_lowercase();
    let args = get_color_args(sub, "color");
    for_each_color(cfg, stdin, &args, |c| {
        if lty == "ansi-8bit-escapecode" {
            print!("{}", ansi_escape_8bit(&c));
        } else if lty == "ansi-24bit-escapecode" {
            print!("{}", ansi_escape_24bit(&c));
        } else {
            let text = format_color(&c, &ty);
            if cfg.mode != ColorModeKind::Off {
                let mut st = Style::new();
                st.fg = Some(c.text_color());
                st.bg = Some(c);
                println!("{}", st.paint(cfg.mode, &text));
            } else {
                println!("{}", text);
            }
        }
        Ok(())
    })
}

fn cmd_list(sub: &clap::ArgMatches, cfg: &Config, rng: &mut Rng) -> error::Result<()> {
    let order = parse_sort_order(sub.get_one::<String>("sort").unwrap());
    let mut v: Vec<(&'static str, Color)> = named::NAMED_COLORS
        .iter()
        .map(|(n, r, g, b)| (*n, Color::from_rgba_u8(*r, *g, *b, 1.0)))
        .collect();
    sort_colors(&mut v, order, rng, |p| &p.1);
    v.dedup_by(|a, b| a.1.to_rgb_u8() == b.1.to_rgb_u8());
    for (name, color) in v {
        if cfg.interactive {
            let text = format!(" {:<23} ", name);
            let mut st = Style::new();
            st.fg = Some(color.text_color());
            st.bg = Some(color);
            println!("{}", st.paint(cfg.mode, &text));
        } else {
            println!("{}", name);
        }
    }
    Ok(())
}

fn cmd_random(sub: &clap::ArgMatches, cfg: &Config, rng: &mut Rng) -> error::Result<()> {
    let count: usize = parse_number(sub.get_one::<String>("number").unwrap())?;
    let strategy = sub.get_one::<String>("strategy").map(|s| s.as_str()).unwrap_or("vivid");
    for _ in 0..count {
        let c = match strategy {
            "rgb" => Color::from_rgba_u8(rng.u8(), rng.u8(), rng.u8(), 1.0),
            "gray" => Color::from_hsl(0.0, 0.0, rng.f64(), 1.0),
            "lch_hue" => Color::from_lch(70.0, 35.0, rng.range(0.0, 360.0), 1.0),
            _ => Color::from_hsl(rng.range(0.0, 360.0), rng.range(0.2, 0.8), rng.range(0.3, 0.7), 1.0),
        };
        print_color(cfg, &c);
    }
    Ok(())
}

fn cmd_sort_by(sub: &clap::ArgMatches, cfg: &Config, stdin: &mut StdIn, rng: &mut Rng) -> error::Result<()> {
    let order = parse_sort_order(sub.get_one::<String>("sort-order").unwrap());
    let args = get_color_args(sub, "color");
    let mut colors = collect_colors(cfg, stdin, &args)?;
    if sub.get_flag("unique") {
        let mut seen = std::collections::HashSet::new();
        colors.retain(|c| seen.insert(c.to_rgb_u8()));
    }
    sort_colors(&mut colors, order, rng, |c| c);
    if sub.get_flag("reverse") {
        colors.reverse();
    }
    for c in &colors {
        print_color(cfg, c);
    }
    Ok(())
}

fn cmd_pick(sub: &clap::ArgMatches, cfg: &Config) -> error::Result<()> {
    let count: usize = parse_number(sub.get_one::<String>("count").unwrap())?;
    picker::print_spectrum()?;
    for _ in 0..count {
        let c = picker::pick_color(cfg.picker.as_deref())?;
        print_color(cfg, &c);
    }
    Ok(())
}

fn cmd_paint(sub: &clap::ArgMatches, cfg: &Config, stdin: &mut StdIn) -> error::Result<()> {
    let color_arg = sub.get_one::<String>("color").unwrap().clone();
    let fg = color_from_arg(&color_arg, cfg, stdin)?;
    let bg = match sub.get_one::<String>("on") {
        Some(s) => Some(parser::parse_color(s).ok_or_else(|| PastelError::ColorParseError(s.clone()))?),
        None => None,
    };
    let texts: Vec<&String> = match sub.get_many::<String>("text") {
        Some(v) => v.collect(),
        None => Vec::new(),
    };
    let text = if texts.is_empty() {
        stdin.read_rest()?
    } else {
        texts.iter().map(|s| s.as_str()).collect::<Vec<_>>().join(" ")
    };
    let mut st = Style::new();
    st.fg = Some(fg);
    st.bg = bg;
    st.bold = sub.get_flag("bold");
    st.italic = sub.get_flag("italic");
    st.underline = sub.get_flag("underline");
    let painted = st.paint(cfg.mode, &text);
    if sub.get_flag("no-newline") {
        print!("{}", painted);
    } else {
        println!("{}", painted);
    }
    Ok(())
}

fn cmd_gradient(sub: &clap::ArgMatches, cfg: &Config, stdin: &mut StdIn) -> error::Result<()> {
    let count: usize = parse_number(sub.get_one::<String>("number").unwrap())?;
    if count <= 1 {
        return Err(PastelError::Message("The specified color count must be larger than one".into()));
    }
    let args = get_color_args(sub, "color");
    if args.len() <= 1 {
        return Err(PastelError::Message("The number of color arguments must be larger than one".into()));
    }
    let space = parse_space(sub.get_one::<String>("colorspace").unwrap());
    let mut stops = Vec::new();
    for a in &args {
        stops.push(color_from_arg(a, cfg, stdin)?);
    }
    let segments = stops.len() - 1;
    for i in 0..count {
        let pos = if count == 1 { 0.0 } else { i as f64 / (count - 1) as f64 };
        let scaled = pos * segments as f64;
        let idx = (scaled.floor() as usize).min(segments - 1);
        let local = scaled - idx as f64;
        let c = interpolate(&stops[idx], &stops[idx + 1], local, space);
        print_color(cfg, &c);
    }
    Ok(())
}

fn cmd_mix(sub: &clap::ArgMatches, cfg: &Config, stdin: &mut StdIn) -> error::Result<()> {
    let base_arg = sub.get_one::<String>("base").unwrap().clone();
    let space_s = sub.get_one::<String>("colorspace").unwrap().clone();
    let fraction_s = sub.get_one::<String>("fraction").unwrap().clone();
    let args = get_color_args(sub, "color");
    let space = parse_space(&space_s);
    for_each_color(cfg, stdin, &args, |other| {
        let base = color_from_arg(&base_arg, cfg, stdin)?;
        let fraction: f64 = parse_number(&fraction_s)?;
        let c = interpolate(&other, &base, fraction, space);
        print_color(cfg, &c);
        Ok(())
    })
}

fn cmd_set(sub: &clap::ArgMatches, cfg: &Config, stdin: &mut StdIn) -> error::Result<()> {
    let property = sub.get_one::<String>("property").unwrap().to_ascii_lowercase();
    let value_s = sub.get_one::<String>("value").unwrap().clone();
    let args = get_color_args(sub, "color");
    for_each_color(cfg, stdin, &args, |c| {
        let value: f64 = parse_number(&value_s)?;
        print_color(cfg, &set_property(c, &property, value));
        Ok(())
    })
}

fn set_property(mut c: Color, property: &str, value: f64) -> Color {
    match property {
        "lightness" => {
            let (l, ch, h) = c.to_lch();
            let _ = l;
            Color::from_lch(value, ch, h, c.alpha)
        }
        "hue" => {
            let (l, ch, _h) = c.to_lch();
            Color::from_lch(l, ch, value, c.alpha)
        }
        "chroma" => {
            let (l, _ch, h) = c.to_lch();
            Color::from_lch(l, value, h, c.alpha)
        }
        "lab-a" => {
            let (l, _a, b) = c.to_lab();
            Color::from_lab(l, value, b, c.alpha)
        }
        "lab-b" => {
            let (l, a, _b) = c.to_lab();
            Color::from_lab(l, a, value, c.alpha)
        }
        "oklab-l" => {
            let (_l, a, b) = c.to_oklab();
            Color::from_oklab(value, a, b, c.alpha)
        }
        "oklab-a" => {
            let (l, _a, b) = c.to_oklab();
            Color::from_oklab(l, value, b, c.alpha)
        }
        "oklab-b" => {
            let (l, a, _b) = c.to_oklab();
            Color::from_oklab(l, a, value, c.alpha)
        }
        "red" | "green" | "blue" => {
            let (r, g, b) = c.to_rgb_u8();
            let v = clamp_minmax(value, 0.0, 255.0) as u8;
            let (r, g, b) = match property {
                "red" => (v, g, b),
                "green" => (r, v, b),
                _ => (r, g, v),
            };
            Color::from_rgba_u8(r, g, b, c.alpha)
        }
        "hsl-hue" => {
            c.hue = normalize_hue(value);
            c
        }
        "hsl-saturation" => {
            c.saturation = clamp01(value);
            c
        }
        "hsl-lightness" => {
            c.lightness = clamp01(value);
            c
        }
        "alpha" => {
            c.alpha = clamp01(value);
            c
        }
        _ => c,
    }
}

fn colorblind(c: &Color, ty: &str) -> Color {
    // Simulation in linear RGB via the Stockman/Hunt LMS transform:
    // linear sRGB -> XYZ -> LMS, replace the missing cone response,
    // then back.  The composite linear-RGB matrices below were fitted
    // to the reference behaviour.
    let m: [[f64; 3]; 3] = match ty {
        "prot" => [
            [0.20814131455589177, 1.0132178339325228, -0.0074906543866984695],
            [0.16268141531402008, 0.7918939563596974, 0.0015628101949919392],
            [-0.00428709499989971, 0.005490643218521396, 1.0003277013174332],
        ],
        "deuter" => [
            [0.38743878693084277, 0.7839875209399988, -0.00588459003289086],
            [0.30257024177320346, 0.6128276132138967, 0.0029142465079342915],
            [-0.025551403589352307, 0.03258637533209498, 0.9998563600208649],
        ],
        _ => [
            [1.0015305616267938, 0.12106292209142443, -0.12839304343428642],
            [-0.001669362413159413, 0.8801606991670858, 0.1273303600227527],
            [0.010745838950626292, 0.8310268299347797, 0.1182814313243285],
        ],
    };
    let (r, g, b) = c.to_rgb_float();
    let (lr, lg, lb) = (linearize(r), linearize(g), linearize(b));
    let nr = m[0][0] * lr + m[0][1] * lg + m[0][2] * lb;
    let ng = m[1][0] * lr + m[1][1] * lg + m[1][2] * lb;
    let nb = m[2][0] * lr + m[2][1] * lg + m[2][2] * lb;
    Color::from_rgba_01(delinearize(nr), delinearize(ng), delinearize(nb), c.alpha)
}

fn cmd_colorcheck() -> error::Result<()> {
    println!();
    println!("8-bit mode:");
    print!("{}", colorcheck_panels(ColorModeKind::Mode8));
    println!("24-bit mode:");
    print!("{}", colorcheck_panels(ColorModeKind::Mode24));
    println!("If your terminal emulator supports 24-bit colors, you should see three square color panels in the lower row and the colors should look similar (but slightly different from) the colors in the top row panels.");
    println!("The panels in the lower row should look like squares that are filled with a uniform color (no stripes or other artifacts).");
    println!();
    println!("You can also open https://github.com/sharkdp/pastel/blob/master/doc/colorcheck.md in a browser to compare how the output should look like.");
    Ok(())
}

fn colorcheck_panels(mode: ColorModeKind) -> String {
    let mut canvas = Canvas::new(30, 12);
    let colors = [(73u8, 39u8, 50u8), (16, 51, 30), (29, 54, 90)];
    for (i, (r, g, b)) in colors.iter().enumerate() {
        canvas.draw_rect(2 + i * 10, 2, 8, 8, Color::from_rgba_u8(*r, *g, *b, 1.0));
    }
    canvas.render(mode)
}

