fn cmd_distinct(sub: &clap::ArgMatches, cfg: &Config, stdin: &mut StdIn, rng: &mut Rng) -> error::Result<()> {
    let count: usize = parse_number(sub.get_one::<String>("count").unwrap())?;
    if count <= 1 {
        return Err(PastelError::Message("The number of colors must be larger than one".into()));
    }
    let verbose = sub.get_flag("verbose");
    let metric_de2000 = sub.get_one::<String>("metric").unwrap() == "CIEDE2000";
    let args = get_color_args(sub, "color");
    // Fixed colours come only from the arguments (stdin is not used here).
    let mut fixed: Vec<Color> = Vec::new();
    for a in &args {
        fixed.push(color_from_arg(a, cfg, stdin)?);
    }
    if fixed.len() > count {
        return Err(PastelError::Message(
            "The number of fixed colors must be smaller than the total number of colors".into(),
        ));
    }
    let result = distinct_colors(count, &fixed, metric_de2000, verbose, rng);
    for c in &result {
        print_color(cfg, c);
    }
    Ok(())
}

fn lab_of(c: &Color) -> (f64, f64, f64) { c.to_lab() }

fn distance_metric(a: (f64, f64, f64), b: (f64, f64, f64), de2000: bool) -> f64 {
    if de2000 { delta_e_2000(a, b) } else { lab_distance(a, b) }
}

fn distinct_colors(count: usize, fixed: &[Color], de2000: bool, verbose: bool, rng: &mut Rng) -> Vec<Color> {
    let n_fixed = fixed.len();
    let mut colors: Vec<Color> = fixed.to_vec();
    while colors.len() < count {
        colors.push(Color::from_rgba_u8(rng.u8(), rng.u8(), rng.u8(), 1.0));
    }
    if n_fixed < count {
        // two simulated-annealing phases
        anneal(&mut colors, n_fixed, de2000, verbose, rng, 100_000, 3.0, 0.773781);
        anneal(&mut colors, n_fixed, de2000, verbose, rng, 200_000, 0.5, 0.903921);
    }
    let ordered = reorder_maximin(&colors, de2000);
    if verbose {
        print_distance_matrix(&ordered, de2000);
    }
    ordered
}

fn compute_nearest(labs: &[(f64, f64, f64)], de2000: bool) -> Vec<f64> {
    let n = labs.len();
    let mut nearest = vec![f64::INFINITY; n];
    for i in 0..n {
        for j in 0..n {
            if i != j {
                let d = distance_metric(labs[i], labs[j], de2000);
                if d < nearest[i] { nearest[i] = d; }
            }
        }
    }
    nearest
}

fn score_dmean(nearest: &[f64], n_free: usize) -> f64 {
    nearest.iter().sum::<f64>() / n_free.max(1) as f64
}

fn anneal(colors: &mut Vec<Color>, n_fixed: usize, de2000: bool, verbose: bool, rng: &mut Rng, iterations: usize, t_start: f64, ratio_5000: f64) {
    let n = colors.len();
    let n_free = n - n_fixed;
    if n_free == 0 { return; }
    let mut labs: Vec<(f64, f64, f64)> = colors.iter().map(|c| lab_of(c)).collect();
    let mut nearest = compute_nearest(&labs, de2000);
    let mut d_mean = score_dmean(&nearest, n_free);
    let k = -ratio_5000.ln() / 5000.0;
    let temp = |i: usize| t_start * (-k * i as f64).exp();
    for i in 0..iterations {
        if verbose && i % 5000 == 0 {
            let d_min = nearest.iter().cloned().fold(f64::INFINITY, f64::min);
            let mut line = format!("[{:10}] D_mean = {:<6.2}; D_min = {:<6.2}; T = {:.6} ", i, d_mean, d_min, temp(i));
            for c in colors.iter() {
                let (r, g, b) = c.to_rgb_u8();
                line.push_str(&format!("{:02x}{:02x}{:02x} ", r, g, b));
            }
            eprintln!("{}", line);
        }
        let t = temp(i);
        let idx = n_fixed + rng.usize_range(n_free);
        let old_color = colors[idx];
        let old_lab = labs[idx];
        let new_color = Color::from_rgba_u8(rng.u8(), rng.u8(), rng.u8(), 1.0);
        let new_lab = lab_of(&new_color);
        // compute new nearest values
        let mut new_nearest = nearest.clone();
        let mut nearest_idx = f64::INFINITY;
        for j in 0..n {
            if j == idx { continue; }
            let d = distance_metric(new_lab, labs[j], de2000);
            if d < nearest_idx { nearest_idx = d; }
        }
        new_nearest[idx] = nearest_idx;
        for j in 0..n {
            if j == idx { continue; }
            let d_new = distance_metric(new_lab, labs[j], de2000);
            // Whether j's nearest was idx is unknown from `nearest`
            // alone; recompute j's nearest if the old distance to idx
            // could have been its minimum.
            let d_old_to_idx = distance_metric(old_lab, labs[j], de2000);
            if d_old_to_idx <= nearest[j] + 1e-12 {
                // recompute across the row
                let mut m = d_new;
                for q in 0..n {
                    if q == j || q == idx { continue; }
                    let dd = distance_metric(labs[j], labs[q], de2000);
                    if dd < m { m = dd; }
                }
                new_nearest[j] = m;
            } else if d_new < new_nearest[j] {
                new_nearest[j] = d_new;
            }
        }
        let new_d_mean = score_dmean(&new_nearest, n_free);
        let delta = new_d_mean - d_mean;
        let accept = delta >= 0.0 || rng.bool_prob((delta / t).exp());
        if accept {
            colors[idx] = new_color;
            labs[idx] = new_lab;
            nearest = new_nearest;
            d_mean = new_d_mean;
        } else {
            let _ = old_color;
        }
    }
}

fn reorder_maximin(colors: &[Color], de2000: bool) -> Vec<Color> {
    if colors.is_empty() { return Vec::new(); }
    let labs: Vec<(f64, f64, f64)> = colors.iter().map(|c| lab_of(c)).collect();
    let mut remaining: Vec<usize> = (1..colors.len()).collect();
    let mut order: Vec<usize> = vec![0];
    while !remaining.is_empty() {
        // choose the colour maximising the minimum distance to the
        // already chosen colours (last maximum wins ties)
        let mut best_pos = 0usize;
        let mut best_val = f64::NEG_INFINITY;
        for (pos, &idx) in remaining.iter().enumerate() {
            let mut m = f64::INFINITY;
            for &sel in &order {
                let d = distance_metric(labs[idx], labs[sel], de2000);
                if d < m { m = d; }
            }
            if m >= best_val {
                best_val = m;
                best_pos = pos;
            }
        }
        order.push(remaining.remove(best_pos));
    }
    order.into_iter().map(|i| colors[i]).collect()
}

fn print_distance_matrix(colors: &[Color], de2000: bool) {
    let labs: Vec<(f64, f64, f64)> = colors.iter().map(|c| lab_of(c)).collect();
    let hex = |c: &Color| {
        let (r, g, b) = c.to_rgb_u8();
        format!("{:02x}{:02x}{:02x}", r, g, b)
    };
    eprintln!();
    eprintln!();
    let mut header = String::from("        ");
    for c in colors {
        header.push_str(&format!("{} ", hex(c)));
    }
    eprintln!("{}", header);
    eprintln!();
    for (i, c) in colors.iter().enumerate() {
        let mut line = format!("{} ", hex(c));
        for j in 0..colors.len() {
            if i == j {
                line.push_str("        ");
            } else {
                line.push_str(&format!("{:7.2} ", distance_metric(labs[i], labs[j], de2000)));
            }
        }
        eprintln!("{}", line);
    }
    eprintln!();
    eprintln!();
}

fn main() -> ExitCode {
    let matches = build_cli().get_matches();
    let cfg = match make_config(&matches) {
        Ok(c) => c,
        Err(e) => {
            print_error(None, &e);
            return ExitCode::from(1);
        }
    };
    match run(&matches, &cfg) {
        Ok(()) => ExitCode::from(0),
        Err(e) => {
            print_error(Some(&cfg), &e);
            ExitCode::from(1)
        }
    }
