//! A minimal, locally written terminal-size provider.
//!
//! This small crate exists so that `clap`'s `wrap_help` feature can be
//! built in an offline environment.  On Unix it queries the window
//! size of stdout/stderr/stdin (in that order) with the `TIOCGWINSZ`
//! ioctl; elsewhere it reports no size.

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Width(pub u16);
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Height(pub u16);

#[cfg(unix)]
pub fn terminal_size() -> Option<(Width, Height)> {
    #[repr(C)]
    #[derive(Default)]
    struct Winsize {
        ws_row: u16,
        ws_col: u16,
        ws_xpixel: u16,
        ws_ypixel: u16,
    }
    #[cfg(any(target_os = "linux", target_os = "macos", target_os = "freebsd", target_os = "netbsd", target_os = "openbsd"))]
    const TIOCGWINSZ: u64 = 0x5413;
    #[cfg(not(any(target_os = "linux", target_os = "macos", target_os = "freebsd", target_os = "netbsd", target_os = "openbsd")))]
    const TIOCGWINSZ: u64 = 0x5413;
    extern "C" {
        fn ioctl(fd: i32, request: u64, ...) -> i32;
    }
    for fd in [1i32, 2, 0] {
        let mut ws = Winsize::default();
        let rc = unsafe { ioctl(fd, TIOCGWINSZ, &mut ws as *mut Winsize) };
        if rc == 0 && ws.ws_col > 0 {
            return Some((Width(ws.ws_col), Height(ws.ws_row)));
        }
    }
    None
}

#[cfg(not(unix))]
pub fn terminal_size() -> Option<(Width, Height)> {
    None
}
RS
python3 - << 'PY'
p="Cargo.toml"; s=open(p).read(); s=s.replace('clap = "4"','clap = { version = "4", features = ["wrap_help"] }')
if "[patch.crates-io]" not in s:
 s += '\n[patch.crates-io]\nterminal_size = { path = "vendor/terminal_size" }\n'
open(p,"w").write(s)
