def make_lab(gamma="srgb",mat=[[0.4124,0.3576,0.1805],[0.2126,0.7152,0.0722],[0.0193,0.1192,0.9505]],wp=(0.95047,1,1.08883),roundto=None):
 def f(c):
  vals=[]
  for x in c:
   v=x/255
   if gamma=="srgb": vals.append(v/12.92 if v<=0.04045 else ((v+.055)/1.055)**2.4)
   elif gamma=="2.2": vals.append(v**2.2)
   elif gamma=="2.4": vals.append(v**2.4)
   elif gamma=="none": vals.append(v)
   elif gamma=="sqrt": vals.append(math.sqrt(v))
  r,g,b=vals; X=r*mat[0][0]+g*mat[0][1]+b*mat[0][2];Y=r*mat[1][0]+g*mat[1][1]+b*mat[1][2];Z=r*mat[2][0]+g*mat[2][1]+b*mat[2][2]
  ff=lambda t:t**(1/3) if t>216/24389 else (24389/27*t+16)/116
  fx,fy,fz=ff(X/wp[0]),ff(Y/wp[1]),ff(Z/wp[2]); out=(116*fy-16,500*(fx-fy),200*(fy-fz))
  if roundto: out=tuple(round(x*roundto)/roundto for x in out)
  return out
