 for lc,ref in zip(CL,refs):
  best=None; bestd=1e18
  for (code,_),lp in zip(pal,PL):
   # de94 asymmetric: reference is first (input) if use_first
   L1,a1,b1=(lc if use_first else lp); L2,a2,b2=(lp if use_first else lc)
