 for col in range(3):
  d=a[col][col]; a[col]=[x/d for x in a[col]]
  for r in range(3):
   if r!=col:
    f=a[r][col]; a[r]=[x-f*y for x,y in zip(a[r],a[col])]
 return [row[3:] for row in a]
B=[[0.8951,0.2664,-0.1614],[-0.7502,1.7135,0.0367],[0.0389,-0.0685,1.0296]]
