 if adapt=="bradford":
  src=mv(B,(0.95047,1,1.08883)); dst=mv(B,(0.9642,1,0.8251)); cone=mv(B,xyz); cone=[cone[i]*dst[i]/src[i] for i in range(3)]; xyz=tuple(mv(inv3(B),cone))
 elif adapt=="xyzscale":
  xyz=(xyz[0]*0.9642/0.95047,xyz[1],xyz[2]*0.8251/1.08883)
 wp=(0.9642,1,0.8251)
 f=lambda t:t**(1/3) if t>216/24389 else (24389/27*t+16)/116
 fx,fy,fz=f(xyz[0]/wp[0]),f(xyz[1]/wp[1]),f(xyz[2]/wp[2]); return (116*fy-16,500*(fx-fy),200*(fy-fz))
