   f=lambda t:t**(1/3) if t>216/24389 else (24389/27*t+16)/116
   fx,fy,fz=f(xyz[0]/wp[0]),f(xyz[1]),f(xyz[2]/wp[2]); return (116*fy-16,500*(fx-fy),200*(fy-fz))
  return lab_d50(c,adapt)
 pl=[getlab(p) for _,p in pal]
 for metric in ["de2000","cie76"]:
  mism=sum(pal[min(range(len(pal)),key=lambda i: deltaE00(getlab(c),pl[i]) if metric=="de2000" else math.dist(getlab(c),pl[i]))][0]!=ref for c,ref in zip(colors,refs))
  print(adapt,metric,mism)
