{"command":"cat > /tmp/fit_ansi13.py << 'PY'
import json,math
D=json.load(open("/tmp/ansi_data.json")); colors=[tuple(x) for x in D["colors"]]; refs=D["refs"]
levels=[0,95,135,175,215,255]; pal=[]
for i in range(216): pal.append((16+i,(levels[i//36],levels[(i//6)%6],levels[i%6])))
for i in range(24): pal.append((232+i,(8+i*10,)*3))
def lin(c):
 c=c/255; return c/12.92 if c<=0.04045 else ((c+.055)/1.055)**2.4
def lab(c):
 r,g,b=[lin(x) for x in c]; X=r*.4124+g*.3576+b*.1805;Y=r*.2126+g*.7152+b*.0722;Z=r*.0193+g*.1192+b*.9505
 f=lambda t:t**(1/3) if t>216/24389 else (24389/27*t+16)/116
 fx,fy,fz=f(X/.95047),f(Y),f(Z/1.08883); return (116*fy-16,500*(fx-fy),200*(fy-fz))
src=open("/tmp/fit_name.py").read(); exec(src[src.index("def deltaE00"):src.index("\nmetrics=")])
pl=[lab(p) for _,p in pal]
def quant(c,bits,mode):
 out=[]
 for v,bit in zip(c,bits):
  sh=8-bit; q=v>>sh
  if mode=="shift": out.append(q<<sh)
  elif mode=="replicate":
   if bit==5: out.append((q<<3)|(q>>2))
   elif bit==6: out.append((q<<2)|(q>>4))
   elif bit==4: out.append((q<<4)|q)
   else: out.append(v)
  elif mode=="center": out.append(min(255,(q<<sh)+(1<<(sh-1))))
  elif mode=="scale": out.append(round(q*255/((1<<bit)-1)))
 return tuple(out)
for bits in [(5,6,5),(5,5,5),(6,6,6),(4,4,4),(6,7,6),(3,3,2)]:
 for mode in ["shift","replicate","center","scale"]:
  mism=sum(pal[min(range(len(pal)),key=lambda i:deltaE00(lab(quant(c,bits,mode)),pl[i]))][0]!=ref for c,ref in zip(colors,refs))
  print(bits,mode,mism)
