p="src/main.rs"; s=open(p).read()
start=s.index("fn colorblind(")
end=s.index("fn cmd_colorcheck()")
new='''fn colorblind(c: &Color, ty: &str) -> Color {
    // Simulation in LMS space: linear sRGB -> XYZ -> LMS (Hunt), the
    // missing cone response is replaced by a combination of the other
    // two, then back through XYZ to linear sRGB.
    let (r, g, b) = c.to_rgb_float();
    let xyz = rgb01_to_xyz(r, g, b);
    const HUNT: [[f64; 3]; 3] = [
        [0.40024, 0.7076, -0.08081],
        [-0.22630, 1.16532, 0.04570],
        [0.0, 0.0, 0.91822],
    ];
    // inverse of HUNT
    const HUNT_INV: [[f64; 3]; 3] = [
        [1.8599363877043544, -1.1293816181379492, 0.21989740959696985],
        [0.3609856479332908, 0.6388124534038948, -7.709825504262337e-6],
        [0.0, 0.0, 1.0890636239218182],
    ];
    let mv = |m: &[[f64; 3]; 3], v: (f64, f64, f64)| -> (f64, f64, f64) {
        (
            m[0][0] * v.0 + m[0][1] * v.1 + m[0][2] * v.2,
            m[1][0] * v.0 + m[1][1] * v.1 + m[1][2] * v.2,
            m[2][0] * v.0 + m[2][1] * v.1 + m[2][2] * v.2,
        )
    };
    let (l, m, s) = mv(&HUNT, xyz);
    let (l, m, s) = match ty {
        "prot" => (1.09635 * m - 0.05724 * s, m, s),
        "deuter" => (l, 0.91213 * l + 0.0522 * s, s),
        _ => (l, m, -0.776 * l + 1.7417 * m),
    };
    let xyz2 = mv(&HUNT_INV, (l, m, s));
    let (r2, g2, b2) = xyz_to_rgb255(xyz2.0, xyz2.1, xyz2.2);
    Color::from_rgba_255(r2, g2, b2, c.alpha)
}

'''
s=s[:start]+new+s[end:]
open(p,"w").write(s)
PY
