python3 - << 'PY'
H=[[0.40024,0.7076,-0.08081],[-0.22630,1.16532,0.04570],[0,0,0.91822]]
def inv3(m):
 a=[row[:]+[1 if i==j else 0 for j in range(3)] for i,row in enumerate(m)]
 for col in range(3):
  d=a[col][col]; a[col]=[x/d for x in a[col]]
  for r in range(3):
   if r!=col:
    f=a[r][col]; a[r]=[x-f*y for x,y in zip(a[r],a[col])]
 return [row[3:] for row in a]
print(inv3(H))
PY"}

