# Replace interpolate_hue with weighted version and update call sites
s=s.replace("""fn interpolate_hue(a: f64, b: f64, t: f64) -> f64 {
    let mut diff = b - a;
    if diff > 180.0 {
        diff -= 360.0;
    } else if diff < -180.0 {
        diff += 360.0;
    }
    let h = (a + diff * t).rem_euclid(360.0);
    if h == 0.0 { 0.0 } else { h }
}""",
"""fn interpolate_hue(a: f64, b: f64, t: f64) -> f64 {
    interpolate_hue_weighted(a, 1.0, b, 1.0, t, 0.0)
}

/// Hue interpolation with "powerless" hues: if one endpoint is
/// (nearly) achromatic, its hue is replaced by the other's.
fn interpolate_hue_weighted(a: f64, wa: f64, b: f64, wb: f64, t: f64, eps: f64) -> f64 {
    let (a, b) = if wa < eps {
        (b, b)
    } else if wb < eps {
        (a, a)
    } else {
        (a, b)
    };
    let mut diff = b - a;
    if diff > 180.0 {
        diff -= 360.0;
    } else if diff < -180.0 {
        diff += 360.0;
    }
    let h = (a + diff * t).rem_euclid(360.0);
    if h == 0.0 { 0.0 } else { h }
}""")
s=s.replace("hue: interpolate_hue(c1.hue, c2.hue, t),", "hue: interpolate_hue_weighted(c1.hue, c1.saturation, c2.hue, c2.saturation, t, 1e-4),")
