"""        let c = if local == 0.0 {
            interpolate(&stops[idx], &stops[idx], 0.0, space)
        } else if local == 1.0 {
            interpolate(&stops[idx + 1], &stops[idx + 1], 0.0, space)
        } else {
            interpolate(&stops[idx], &stops[idx + 1], local, space)
        };
        print_color(cfg, &c);""")
