p="src/main.rs"; s=open(p).read()
start=s.index("fn anneal(")
end=s.index("fn reorder_maximin(")
new='''fn anneal(colors: &mut Vec<Color>, n_fixed: usize, de2000: bool, verbose: bool, rng: &mut Rng, iterations: usize, t_start: f64, k: f64) {
    let n = colors.len();
    let n_free = n - n_fixed;
    if n_free == 0 { return; }
    let mut labs: Vec<(f64, f64, f64)> = colors.iter().map(|c| lab_of(c)).collect();
    // Cached pairwise distance matrix (updated for the mutated index).
    let mut dist: Vec<Vec<f64>> = vec![vec![0.0; n]; n];
    for i in 0..n {
        for j in 0..n {
            if i != j {
                dist[i][j] = distance_metric(labs[i], labs[j], de2000);
            }
        }
    }
    let mut nearest: Vec<f64> = (0..n)
        .map(|i| (0..n).filter(|&j| j != i).map(|j| dist[i][j]).fold(f64::INFINITY, f64::min))
        .collect();
    let mut d_mean = score_dmean(&nearest, n_free);
    let temp = |i: usize| t_start * (-k * i as f64).exp();
    for i in 0..iterations {
        if verbose && i % 5000 == 0 {
            let d_min = nearest.iter().cloned().fold(f64::INFINITY, f64::min);
            let mut line = format!("[{:10}] D_mean = {:<6.2}; D_min = {:<6.2}; T = {:.6} ", i, d_mean, d_min, temp(i));
            for c in colors.iter() {
                let (r, g, b) = c.to_rgb_u8();
                line.push_str(&format!("{:02x}{:02x}{:02x} ", r, g, b));
            }
            eprintln!("{}", line);
        }
        let t = temp(i);
        let idx = n_fixed + rng.usize_range(n_free);
        let new_color = Color::from_rgba_u8(rng.u8(), rng.u8(), rng.u8(), 1.0);
        let new_lab = lab_of(&new_color);
        let new_dists: Vec<f64> = (0..n)
            .map(|j| if j == idx { 0.0 } else { distance_metric(new_lab, labs[j], de2000) })
            .collect();
        let mut new_nearest = nearest.clone();
        new_nearest[idx] = (0..n).filter(|&j| j != idx).map(|j| new_dists[j]).fold(f64::INFINITY, f64::min);
        for j in 0..n {
            if j == idx { continue; }
            if dist[j][idx] <= nearest[j] + 1e-12 {
                // The mutated colour may have been j's nearest: rescan.
                let mut m = new_dists[j];
                for q in 0..n {
                    if q != j && q != idx && dist[j][q] < m {
                        m = dist[j][q];
                    }
                }
                new_nearest[j] = m;
            } else if new_dists[j] < new_nearest[j] {
                new_nearest[j] = new_dists[j];
            }
        }
        let new_d_mean = score_dmean(&new_nearest, n_free);
        let delta = new_d_mean - d_mean;
        if delta >= 0.0 || rng.bool_prob((delta / t).exp()) {
            colors[idx] = new_color;
            labs[idx] = new_lab;
            for j in 0..n {
                dist[idx][j] = new_dists[j];
                dist[j][idx] = new_dists[j];
            }
            nearest = new_nearest;
            d_mean = new_d_mean;
        }
    }
}

'''
s=s[:start]+new+s[end:]
